from typing import List

Edge = str

def comp(e: Edge) -> Edge:
    return {"flat": "flat", "tab": "blank", "blank": "tab"}[e]

def wt(e: Edge) -> int:
    return {"flat": 0, "tab": 1, "blank": -1}[e]

def strip_potential(rights: List[Edge], lefts: List[Edge]) -> int:
    """Total potential along a valid interface strip; equals 0 by the
    telescoping conservation lemma."""
    n = len(rights)
    assert len(lefts) == n
    if n > 0:
        assert lefts[0] == "flat" and rights[n - 1] == "flat"
        assert all(lefts[i + 1] == comp(rights[i]) for i in range(n - 1))
    return sum(wt(rights[i]) + wt(lefts[i]) for i in range(n))

from typing import List, Tuple

Edge = str
Piece = Tuple[Edge, Edge, Edge, Edge]  # (top, right, bottom, left)

def comp(e: Edge) -> Edge:
    return {"flat": "flat", "tab": "blank", "blank": "tab"}[e]

def wt(e: Edge) -> int:
    return {"flat": 0, "tab": 1, "blank": -1}[e]

def grid_conservation(grid: List[List[Piece]]) -> Tuple[int, int, int]:
    R, C = len(grid), len(grid[0]) if grid else 0
    for j in range(C):
        assert grid[0][j][0] == "flat" and grid[R - 1][j][2] == "flat"
    for i in range(R):
        assert grid[i][0][3] == "flat" and grid[i][C - 1][1] == "flat"
    for i in range(R):
        for j in range(C):
            if j + 1 < C:
                assert grid[i][j + 1][3] == comp(grid[i][j][1])
            if i + 1 < R:
                assert grid[i + 1][j][0] == comp(grid[i][j][2])
    total = sum(wt(e) for line in grid for cell in line for e in cell)
    tabs = sum(e == "tab" for line in grid for cell in line for e in cell)
    blanks = sum(e == "blank" for line in grid for cell in line for e in cell)
    return total, tabs, blanks

