function INTERLOCK_AUTOMORPHISMS(alphabet, comp):
    group <- empty list
    for each permutation sigma of alphabet:
        if for all e: sigma(comp(e)) == comp(sigma(e)):
            append sigma to group
    return group        # the automorphism group of the matching relation
